styles.css:
& .wp-block-button__link { transition: all 0.2s ease; }
& .wp-block-button__link:hover { background-color: var(--wp--preset--color--secondary); }
& .wp-block-button__link:active { background-color: var(--wp--preset--color--secondary); }
& .wp-block-button__link:focus { outline: 2px solid var(--wp--preset--color--accent); outline-offset: 2px; }
& .wp-block-button__link:focus-visible { outline: 2px solid var(--wp--preset--color--accent); outline-offset: 2px; }
